#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "nussinov.h"

/* RNA bases represented as chars, range is [0,3] */
typedef char base;

#define match(b1, b2) (((b1)+(b2)) == 3 ? 1 : 0)
#define max_score(s1, s2) ((s1 >= s2) ? s1 : s2)

/* Tunable parameter:
 * For very small problems, parallelization overhead can dominate.
 * Only enable OpenMP parallelism for sizes n >= NUSSINOV_OMP_MIN_SIZE.
 */
#ifndef NUSSINOV_OMP_MIN_SIZE
# define NUSSINOV_OMP_MIN_SIZE 64
#endif

/* Array initialization. */
static
void init_array (int n,
                 base POLYBENCH_1D(seq,N,n),
		 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j;

  //base is AGCT/0..3
  for (i=0; i <n; i++) {
     seq[i] = (base)((i+1)%4);
  }

  for (i=0; i <n; i++)
     for (j=0; j <n; j++)
       table[i][j] = 0;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))

{
  int i, j;
  int t = 0;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("table");
  for (i = 0; i < n; i++) {
    for (j = i; j < n; j++) {
      if (t % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, table[i][j]);
      t++;
    }
  }
  POLYBENCH_DUMP_END("table");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimized version:
   - Reorders loops to iterate by increasing subsequence length (j - i),
     which improves data locality and exposes diagonal parallelism.
   - Uses local restrict-qualified pointers for better alias analysis.
   - Accumulates the best score in a scalar variable to reduce
     redundant memory reads/writes.
   - Optionally parallelizes the independent work on each diagonal
     with OpenMP (if compiled with -fopenmp).
*/
static void __attribute__((noinline))
kernel_nussinov(int n,
                base POLYBENCH_1D(seq,N,n),
		DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  /* PolyBench provides a possibly adjusted loop bound through _PB_N.
     Use it for the iteration space, but keep the full-size 'n' for
     the actual array extents. */
  const int n_pb   = _PB_N;
  const int n_cols = n;

  /* Create local restrict-qualified views.  The underlying storage is
     still the same, but this gives the compiler stronger guarantees
     about aliasing, enabling better optimization. */
  base * __restrict seq_local = seq;
  DATA_TYPE (* __restrict T)[n] = table;

#pragma scop
  /* Iterate over subsequence lengths (distance between i and j).
     All dependencies of table[i][j] are on entries with smaller
     (j - i), so processing by increasing 'len' is valid. */
  for (int len = 1; len < n_pb; ++len) {

    /* For a fixed 'len', all (i, j = i+len) pairs are independent:
       each depends only on entries with smaller lengths.  This is a
       natural place for parallelism across i. */
#if defined(_OPENMP)
#pragma omp parallel for schedule(static) if (n_pb >= NUSSINOV_OMP_MIN_SIZE)
#endif
    for (int i = 0; i < n_pb - len; ++i) {
      int j = i + len;

      /* Row pointers to avoid recomputing address arithmetic. */
      DATA_TYPE * __restrict Ti   = T[i];
      DATA_TYPE * __restrict Tip1 = T[i+1];

      /* Start from the current value (initialized to 0 in init_array). */
      DATA_TYPE q = Ti[j];
      DATA_TYPE v;

      /* Case 1: extend from the left: table[i][j-1] */
      v = Ti[j-1];
      if (v > q) q = v;

      /* Case 2: extend from below: table[i+1][j] */
      v = Tip1[j];
      if (v > q) q = v;

      /* Case 3: consider pairing i and j (or not), using the diagonal
         table[i+1][j-1].  The original code allows a pair only when
         there is at least one base between i and j (i < j-1).  Here,
         that's equivalent to len >= 2. */
      v = Tip1[j-1];
      if (len >= 2) {
        v += match(seq_local[i], seq_local[j]);
      }
      if (v > q) q = v;

      /* Case 4: split the interval [i, j] at position k.
         This is only relevant when there is space to split (len >= 2).
         We keep the original recurrence:
           table[i][j] = max_{k in (i, j)} table[i][k] + table[k+1][j]
      */
      if (len >= 2) {
        for (int k = i + 1; k < j; ++k) {
          DATA_TYPE cand = Ti[k] + T[k+1][j];
          if (cand > q) q = cand;
        }
      }

      /* Commit the best score for interval [i, j]. */
      Ti[j] = q;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_nussinov (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(table)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(seq);
  POLYBENCH_FREE_ARRAY(table);

  return 0;
}
