typedef char base;

#define match(b1, b2) (((b1)+(b2)) == 3 ? 1 : 0)
#define max_score(s1, s2) ((s1 >= s2) ? s1 : s2)

/* Array initialization. */
static
void init_array (int n,
                 base POLYBENCH_1D(seq,N,n),
                 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i;

  /* base is AGCT/0..3 */
  for (i = 0; i < n; i++) {
    /* (i+1) % 4, but using & 3 is equivalent for non-negative i and cheaper. */
    seq[i] = (base)((i + 1) & 3);
  }

  /* Table is a full n x n array; zero-initialize row by row to maximize
     use of memset and improve store bandwidth. */
  for (i = 0; i < n; i++)
    memset(table[i], 0, (size_t)n * sizeof(DATA_TYPE));
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))

{
  int i, j;
  int t = 0;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("table");
  for (i = 0; i < n; i++) {
    for (j = i; j < n; j++) {
      if (t % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
      fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, table[i][j]);
      t++;
    }
  }
  POLYBENCH_DUMP_END("table");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/*
  Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
  with help from Allison Lake, Ting Zhou, and Tian Jin,
  based on algorithm by Nussinov, described in Allison Lake's senior thesis.
*/

/* Use GCC attribute syntax in C for clarity; keep function out-of-line so that
   the timing done in main measures only this kernel. */
static void __attribute__((noinline))
kernel_nussinov (int n,
                 base POLYBENCH_1D(seq,N,n),
                 DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  int i, j, k, len;

  /* The original loop nest:
       for (i = _PB_N-1; i >= 0; --i)
         for (j = i+1; j < _PB_N; ++j)
     visits each (i,j) with i < j exactly once, in a particular order.

     Here we transform the iteration space to work on increasing
     subsequence lengths "len = j - i".  For a fixed length, all
     (i,j) with j-i == len are *independent*, because every dependence
     in the DP points to strictly shorter subsequences:

       - table[i][j-1]  has length (j-1 - i)     = len-1
       - table[i+1][j]  has length (j - (i+1))   = len-1
       - table[i+1][j-1] length (j-1 - (i+1))    = len-2
       - table[i][k]      length (k   - i)       < len
       - table[k+1][j]    length (j   - (k+1))   < len

     This diagonal (wavefront) traversal exposes parallelism across each
     length "len" while preserving all data dependencies.
   */

#pragma scop
  for (len = 1; len < _PB_N; ++len) {

    /* All (i,j) with fixed len are independent => parallelize over i.
       Each thread writes to disjoint table[i][j], so no synchronization
       is needed.  Guard with _OPENMP so the code also compiles without
       OpenMP enabled (pragmas then vanish). */
#ifdef _OPENMP
#pragma omp parallel for private(i, j, k) schedule(static)
#endif
    for (i = 0; i < _PB_N - len; ++i) {
      j = i + len;

      /* Local aliases to improve locality and give the compiler more
         room to optimize. */
      base si = seq[i];
      base sj = seq[j];
      DATA_TYPE *restrict table_i = table[i];

      /* Start from the two simple recurrence cases:
         - extending from the left:  table[i][j-1]
         - extending from below:     table[i+1][j]
         In the original code, table[i][j] starts at 0 and each of these
         is combined using max_score.  Because table[][] is initialized
         to 0 and each cell is written once, starting from the max of
         these two neighbors is equivalent and saves a few loads/stores. */

      DATA_TYPE best = table_i[j-1];          /* table[i][j-1] */
      DATA_TYPE val  = table[i+1][j];         /* table[i+1][j] */
      if (val > best)
        best = val;

      /* Case where i and j may form a pair, based on table[i+1][j-1].
         The original code did:
            if (i < j-1)
              best = max(best, table[i+1][j-1] + match(...));
            else
              best = max(best, table[i+1][j-1]);
         We implement the same logic without branches on bounds;
         note that when j == i+1 (adjacent), i<j-1 is false and we
         *do not* add the match score, preserving the "no adjacent
         pairing" rule. */
      val = table[i+1][j-1];
      if (i < j-1)
        val += match(si, sj);
      if (val > best)
        best = val;

      /* Bifurcation case:
           best = max_k ( table[i][k] + table[k+1][j] ), i < k < j
         For fixed (i,j), table[i][k] accesses are contiguous in memory,
         improving cache locality by using the row pointer table_i. */
      for (k = i + 1; k < j; ++k) {
        DATA_TYPE cand = table_i[k] + table[k+1][j];
        if (cand > best)
          best = cand;
      }

      /* Write final result for this (i,j). */
      table_i[j] = best;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_nussinov (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(table)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(seq);
  POLYBENCH_FREE_ARRAY(table);

  return 0;
}
