                     DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  /* The parameter n and the macro _PB_N carry the same value in
     PolyBench; n is only used to instantiate the VLA type in the
     function signature. To keep the original semantics, we drive
     the loop bounds from _PB_N as in the reference code. */
  (void)n;

  int i, j, k, L;
  base *restrict s = seq;

#pragma scop
  const int N = _PB_N;

  /* The DP table is fully zero-initialized in init_array().
     In the original kernel, the first off-diagonal entries
     table[i][i+1] are *always* left equal to zero:

       - Adjacent bases are forbidden to pair (i < j-1 is false),
       - All their dependencies (table[i][i], table[i+1][i+1],
         and table[i+1][i]) are never written elsewhere and
         therefore stay at zero,
       - The k-loop is empty when j == i+1.

     Thus, skipping explicit computation for j == i+1 is safe:
     those entries remain zero, exactly as in the original code.
     This slightly reduces the work while preserving semantics. */

  /* Main dynamic-programming loop over increasing subsequence length
     L = j - i.  All dependencies of table[i][j] lie on strictly
     smaller diagonals (smaller L), so each diagonal (fixed L) can be
     processed in parallel over i. */
  for (L = 2; L < N; ++L) {
    int max_i = N - L;

    /* Wavefront parallelism: for fixed L, each (i,j=i+L) update
       writes a distinct table[i][j] and reads only entries from
       smaller diagonals.  There are no cross-iteration data
       dependencies across different i for the same L. */
#pragma omp parallel for private(i,j,k) schedule(static)
    for (i = 0; i < max_i; ++i) {
      j = i + L;

      /* Cache frequently used rows to improve locality and to
         help the compiler generate efficient code.  Each pointer
         refers to a distinct, non-overlapping row. */
      DATA_TYPE *restrict table_i   = table[i];
      DATA_TYPE *restrict table_ip1 = table[i + 1];

      /* Start from the current value (initialized to zero by
         init_array and never written before this point). */
      DATA_TYPE v = table_i[j];

      /* 1) Left neighbor: table[i][j-1]. */
      DATA_TYPE cand = table_i[j - 1];
      if (cand > v) v = cand;

      /* 2) Below neighbor: table[i+1][j]. */
      cand = table_ip1[j];
      if (cand > v) v = cand;

      /* 3) Pairing i and j, allowed because L >= 2 ⇒ j - i >= 2
            ⇒ i < j - 1 holds (non-adjacent bases).
           This mirrors the original:
             table[i+1][j-1] + match(seq[i], seq[j])
         and does NOT add the plain table[i+1][j-1] case for
         non-adjacent bases, which the reference code also omits. */
      cand = table_ip1[j - 1] + (DATA_TYPE)match(s[i], s[j]);
      if (cand > v) v = cand;

      /* 4) Bifurcation: split between i and j at every k
            with i < k < j.
           Candidate is table[i][k] + table[k+1][j] as in the
           original kernel. */
      for (k = i + 1; k < j; ++k) {
        DATA_TYPE cand_split = table_i[k] + table[k + 1][j];
        if (cand_split > v) v = cand_split;
      }

      /* Write back the best score for subsequence [i, j]. */
      table_i[j] = v;
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_1D_ARRAY_DECL(seq, base, N, n);
  POLYBENCH_2D_ARRAY_DECL(table, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_nussinov (n, POLYBENCH_ARRAY(seq), POLYBENCH_ARRAY(table));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(table)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(seq);
  POLYBENCH_FREE_ARRAY(table);

  return 0;
}
