/* Main computational kernel. The whole function will be timed,
   including the call and return. */
/*
  Original version by Dave Wonnacott at Haverford College <davew@cs.haverford.edu>,
  with help from Allison Lake, Ting Zhou, and Tian Jin,
  based on algorithm by Nussinov, described in Allison Lake's senior thesis.
*/
static void __attribute__((flatten, noinline))
kernel_nussinov(int n,
                base POLYBENCH_1D(seq,N,n),
	        DATA_TYPE POLYBENCH_2D(table,N,N,n,n))
{
  /* Local restrict-qualified aliases to help the optimizer.
     'n' is the leading dimension of 'table'. */
  base const * restrict seq_      = seq;
  DATA_TYPE (* restrict table_)[n] = table;

  /* Use PolyBench-provided loop bound for the DP size. */
  const int N_ = _PB_N;

#pragma scop
  /* Reordered DP to process along increasing subsequence length (j - i).
     For a fixed length 'len', all (i, j=i+len) cells depend only on
     entries corresponding to shorter lengths, so they are independent
     and can be computed in parallel. */
#pragma omp parallel
  {
    for (int len = 1; len < N_; ++len) {
      /* All (i, j=i+len) for a fixed 'len' are independent. */
#pragma omp for schedule(static)
      for (int i = 0; i < N_ - len; ++i) {
        const int j = i + len;

        /* Row pointers to improve cache locality and reduce indexing cost. */
        DATA_TYPE * restrict table_i   = table_[i];
        DATA_TYPE * restrict table_ip1 = table_[i + 1];

        /* Start with best = max(table[i][j-1], table[i+1][j]).
           In the original code, table[i][j] starts from 0 and is
           successively max'ed with these values. Since all DP values
           are non-negative, starting from table[i][j-1] is equivalent:
           max(0, a, b, ...) == max(a, b, ...) when a, b, ... >= 0. */
        DATA_TYPE best = table_i[j - 1];
        DATA_TYPE tmp  = table_ip1[j];
        if (tmp > best)
          best = tmp;

        /* Case where i and j pair:
             - Adjacent bases (len == 1) are not allowed to pair.
             - Non-adjacent bases can pair if (seq[i] + seq[j]) == 3.
           Original:
             if (i < j-1)
               table[i][j] = max(table[i][j], table[i+1][j-1] + match(...));
             else
               table[i][j] = max(table[i][j], table[i+1][j-1]);
           We implement this as:
             pair_score = (len > 1 && match(...));
             candidate  = table[i+1][j-1] + pair_score;
        */
        const base si = seq_[i];
        const base sj = seq_[j];
        const int pair_score =
          (len > 1) && (((int)si + (int)sj) == 3); /* == match(si, sj) */

        tmp = table_ip1[j - 1] + (DATA_TYPE)pair_score;
        if (tmp > best)
          best = tmp;

        /* Bifurcation: try all possible splits k between i and j.
           Original:
             for (k = i+1; k < j; ++k)
               table[i][j] = max(table[i][j], table[i][k] + table[k+1][j]);
           We accumulate the maximum in 'best' and write once. */
        for (int k = i + 1; k < j; ++k) {
          DATA_TYPE const cand = table_i[k] + table_[k + 1][j];
          if (cand > best)
            best = cand;
        }

        /* Single write of the final best value for this (i, j). */
        table_i[j] = best;
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
